use strict; use warnings;
my "'$in="run_trace/intermediate/edgeR_normal_COVID19.tsv";
my $out="final_answer/differential_expression.tsv";
open my $fh,"<",$in or die $!;
my $h=<$fh>; chomp $h; my @h=split /'"\\t/,"'$h,-1; my %idx; @idx{@h}=0..$#h;
for my $need (qw(GeneID logFC PValue)){ die "missing $need'"\\n\" unless exists "'$idx{$need}; }
my @rows;
while(<$fh>){ chomp; next unless length; my @f=split /'"\\t/,"'$_,-1; my ($g,$lfc,$p)=@f[@idx{qw(GeneID logFC PValue)}]; die "bad numeric for $g'"\\n\" unless defined "'$lfc && $lfc =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/ && defined $p && $p =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/; $lfc+=0; $p+=0; die "nonfinite lfc $g'"\\n\" if "'$lfc != $lfc || $lfc == 9**9**9 || $lfc == -9**9**9; die "bad p $g $p'"\\n\" if "'$p < 0 || $p > 1 || $p != $p; push @rows,{gene=>$g,lfc=>$lfc,p=>$p}; }
close $fh;
my $m=@rows;
my @ord=sort { $rows[$a]{p} <=> $rows[$b]{p} || $a <=> $b } 0..$#rows;
my @adj=(0)x$m; my $prev=1;
for(my $rank=$m; $rank>=1; $rank--){ my $i=$ord[$rank-1]; my $val=$rows[$i]{p}*$m/$rank; $val=1 if $val>1; $prev=$val if $val<$prev; $adj[$i]=$prev; }
open my $of,">",$out or die $!;
print $of "gene'"\\tlog2_fold_change\\tp_value\\tfdr\\n\";
for my "'$i (0..$#rows){ printf $of "%s'"\\t%.15g\\t%.15g\\t%.15g\\n\", "'$rows[$i]{gene}, $rows[$i]{lfc}, $rows[$i]{p}, $adj[$i]; }
close $of;
print "wrote $m DE rows'"\\n\";
'"

